import { MeshStandardNodeMaterial, MeshBasicNodeMaterial, PlaneGeometry, Group, Mesh } from 'three/webgpu';
import { mix, uv, vec3, float } from 'three/tsl';
import { gsap } from 'gsap';
import { } from '@/primitives';
import { } from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root group
  const root = new Group();
  root.name = 'FilmstripCarousel';

  // ---------- Background Gradient ----------
  const bgGeom = new PlaneGeometry(7, 6);
  const bgMat = new MeshBasicNodeMaterial();
  bgMat.colorNode = mix(vec3(0x0b0b10), vec3(0x12121a), uv().y);
  const bgMesh = new Mesh(bgGeom, bgMat);
  bgMesh.position.z = -2.5;
  root.add(bgMesh);

  // ---------- Text Content ----------
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items[0] ?? { text: 'The collection' };
  const bodyItem = items[1] ?? { text: 'Five calibres. One discipline.' };
  const captionItems = items.slice(2);

  const headline = ctx.fontAtlas.createText(headlineItem.text, {
    fontSize: 68,
    color: '#e8ecf2',
    align: 'left',
  });
  headline.position.set(-2.6, 1.5, 0);
  root.add(headline);

  const body = ctx.fontAtlas.createText(bodyItem.text, {
    fontSize: 26,
    color: '#e8ecf2',
    align: 'left',
  });
  body.position.set(-2.6, -1.5, 0);
  root.add(body);

  // ---------- Card Strip ----------
  const stripGroup = new Group();
  stripGroup.rotation.y = -Math.PI / 180 * 18; // -18deg
  const pitch = 1.85;
  const cardWidth = 1.6;
  const cardHeight = 1.0;
  const bevelSize = 0.025;
  const cardMaterials = [];
  const cardMeshes = [];

  // Load texture (single texture used for all cards as placeholder)
  let loadedTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    loadedTexture = tex;
    cardMaterials.forEach((mat) => {
      mat.map = tex;
      mat.needsUpdate = true;
    });
  });

  // Create cards
  for (let i = 0; i < 5; i++) {
    const isFocused = i === 2;
    const cardGroup = new Group();
    cardGroup.position.x = (i - 2) * pitch;

    // Counter‑rotate focused card to face camera
    if (isFocused) {
      cardGroup.rotation.y = Math.PI / 180 * 18;
    }

    // Scale
    const scaleFactor = isFocused ? 1.0 : 0.92;
    cardGroup.scale.setScalar(scaleFactor);

    // Opacity
    const distance = Math.abs(i - 2);
    const opacity = 1 - (distance / 2) * 0.45; // 1.0 → 0.55

    // ---- Bevel Frame ----
    const frameGeom = new PlaneGeometry(cardWidth + bevelSize * 2, cardHeight + bevelSize * 2);
    const frameMat = new MeshStandardNodeMaterial({
      color: '#16161d',
      metalness: 0,
      roughness: 1,
      transparent: false,
    });
    const frameMesh = new Mesh(frameGeom, frameMat);
    frameMesh.position.z = -0.001;
    cardGroup.add(frameMesh);

    // ---- Card Plane ----
    const cardGeom = new PlaneGeometry(cardWidth, cardHeight);
    const cardMat = new MeshStandardNodeMaterial({
      metalness: 0.2,
      roughness: 0.55,
      clearcoat: 0.15,
      transparent: true,
      opacity: opacity,
    });
    // map will be assigned after texture load
    const cardMesh = new Mesh(cardGeom, cardMat);
    cardMesh.position.z = 0.001;
    cardGroup.add(cardMesh);

    // Store for later disposal
    cardMaterials.push(cardMat);
    cardMeshes.push(cardMesh, frameMesh);

    // ---- Underline for focused card ----
    if (isFocused) {
      const underlineGeom = new PlaneGeometry(cardWidth, 0.035);
      const underlineMat = new MeshStandardNodeMaterial({
        color: '#ff2a38',
        emissive: '#ff2a38',
        emissiveIntensity: 1.3,
        metalness: 0,
        roughness: 1,
        transparent: true,
      });
      const underline = new Mesh(underlineGeom, underlineMat);
      underline.position.set(0, -cardHeight / 2 - 0.0175, 0.002);
      cardGroup.add(underline);
      // Store
      cardMeshes.push(underline);
    }

    // ---- Caption Text ----
    const captionItem = captionItems[i];
    if (captionItem) {
      const caption = ctx.fontAtlas.createText(captionItem.text, {
        fontSize: 18,
        color: '#16161d',
        align: 'center',
      });
      caption.position.set(0, -cardHeight / 2 - 0.08, 0.003);
      cardGroup.add(caption);
    }

    stripGroup.add(cardGroup);
  }

  root.add(stripGroup);

  // ---------- Cinematic Primitives ----------
  const primitiveHandles = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      if (prim && prim.name && ctx.primitives[prim.name]) {
        const handle = ctx.primitives[prim.name](root, prim.params || {});
        primitiveHandles.push(handle);
      }
    }
  }

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    bgGeom.dispose();
    bgMat.dispose();

    cardMeshes.forEach((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) obj.material.dispose();
    });

    if (loadedTexture) loadedTexture.dispose();

    // Cleanup primitives
    primitiveHandles.forEach((h) => {
      if (h && typeof h.cleanup === 'function') h.cleanup();
    });

    // Kill any GSAP timelines (none in this node, but safe)
    gsap.killTweensOf(root);
  };

  // ---------- Event Handlers (none) ----------
  root.userData.handlers = {};

  return root;
}
